46:   groupAssistantParts,
47:   type NonReasoningPart,
48: } from "./group-assistant-parts";
49: import { hasVisibleContent, isVisibleSegment } from "./message-visibility";
50: import { InstructionsPart } from "./instructions-part";
51: import { MessageAttachments } from "./message-attachments";
52: import { MessageCopyButton } from "./message-copy-button";
53: import { MessageForkButton } from "./message-fork-button";
