144: /** The dedicated row for a tool, or `null` when it has none. A stored
145:  *  `read` image result's thumbnail loads the `/model` route and its lightbox
146:  *  the `/original` route. */
147: function dedicatedToolRow(
148:   toolName: string,
149:   props: ToolPartProps,
150:   renderers: ChatMarkdownRenderers,
151: ): ReactNode {
152:   switch (toolName) {
153:     case "read":
154:       return (
155:         <ReadTool
156:           {...props}
157:           Markdown={renderers.MessageResponse}
158:           mediaSources={storedImageSources}
159:         />
