147: function dedicatedToolRow(
148:   toolName: string,
149:   props: ToolPartProps,
150:   renderers: ChatMarkdownRenderers,
151: ): ReactNode {
152:   switch (toolName) {
153:     case "read":
154:       return (
155:         <ReadTool
156:           {...props}
157:           Markdown={renderers.MessageResponse}
158:           mediaSources={storedImageSources}
159:         />
160:       );
161:     case "web_search":
162:       return <WebSearchTool {...props} Markdown={renderers.MessageResponse} />;
163:     case "bash":
164:       return <BashTool {...props} />;
165:     case "edit":
166:       return <EditTool {...props} />;
167:     case "write":
168:       return <WriteTool {...props} />;
169:     case "grep":
170:       return <GrepTool {...props} />;
171:     case "search_conversations":
172:       return <SearchConversationsTool {...props} />;
173:     case "conversation_read":
174:       return <ConversationReadTool {...props} />;
175:     case "knowledge_search":
176:       return <KnowledgeSearchTool {...props} />;
177:     case "enter_workspace":
178:     case "exit_workspace":
179:       return <WorkspaceTool {...props} name={toolName} />;
180:     default:
181:       return toolName.startsWith("mcp__") ? (
182:         <McpTool {...props} name={toolName} />
183:       ) : null;
184:   }
185: }
186: 
187: /** A tool call/result: its dedicated row, else the generic tool block. */
188: function ToolUIPartView({
189:   part,
190:   renderers,
191: }: {
192:   part: ToolUIPart | DynamicToolUIPart;
193:   renderers: ChatMarkdownRenderers;
194: }) {
195:   const row = dedicatedToolRow(
196:     getToolName(part),
197:     {
198:       input: part.input,
199:       output: part.output,
200:       errorText: part.errorText,
201:       state: toolHeaderState(part),
202:     },
203:     renderers,
204:   );
205:   return row ?? <ToolPartView part={part} />;
206: }
207: 
208: /** Renders one non-reasoning message part — text, a tool call/result, a
209:  *  step-cap notice, the instructions or prompt-imports chip, or a
210:  *  server-authored context item this build does not render (the walk
211:  *  withholds those before they reach here). */
212: function MessagePartView({
213:   part,
214:   renderers,
215: }: {
216:   part: NonReasoningPart;
217:   renderers: ChatMarkdownRenderers;
218: }) {
219:   if (part.type === "text") {
220:     const MessageResponse = renderers.MessageResponse;
221:     return <MessageResponse>{part.text}</MessageResponse>;
222:   }
223:   if (isToolUIPart(part)) {
224:     return <ToolUIPartView part={part} renderers={renderers} />;
225:   }
226:   if (part.type === "data-cap-notice") {
227:     // Step-cap notice (D6): persisted alongside the tool call/result parts
228:     // when a run hits tools.maxStepsPerRun. Same part → same chip, live or
229:     // reloaded from history.
230:     const capNotice = parseCapNoticePart(part);
231:     return capNotice ? <ToolCapNoticePart {...capNotice} /> : null;
232:   }
233:   if (isInstructionsPart(part)) {
234:     return <InstructionsPart {...part.data.payload} />;
235:   }
236:   if (isPromptImportsPart(part)) {
237:     return <PromptImportsPart {...part.data.payload} />;
238:   }
239:   return <span>unsupported part type: {part.type}</span>;
240: }
241: 
242: /** What one transcript row paints: its stored parts, the pending indicator in
243:  *  their place, or nothing at all. */
244: export type MessageRowMode = "content" | "pending" | "hidden";
245: 
246: /**
247:  * The row's render decision for an assistant turn with no visible content.
248:  *
249:  * While the chat is in flight the last row is the turn being produced, so it
250:  * carries the pending indicator — including after a Stop the server has not
251:  * settled yet (M3's S4), which is a state of the composer, not of the turn.
252:  * Any other such turn is either a live placeholder whose Run was stopped
253:  * before its model request, which persists no assistant message and which
254:  * history adoption keeps in the live list wherever later turns move it — that
255:  * row paints nothing, fork action included, because its id is a Run id — or a
256:  * persisted empty turn (it carries a `seq`), which renders as today so its
257:  * "stopped" usage stays readable.
258:  */
259: export function messageRowMode({
260:   message,
261:   isLast,
262:   status,
263: }: {
264:   message: UIMessage;
265:   isLast: boolean;
266:   status: ChatStatus;
267: }): MessageRowMode {
268:   if (message.role !== "assistant") return "content";
269:   if (hasVisibleContent(message.parts)) return "content";
270:   if (isLast && (status === "submitted" || status === "streaming")) {
271:     return "pending";
272:   }
273:   return messageSeqFromMetadata(message.metadata) === null
274:     ? "hidden"
275:     : "content";
276: }
277: 
278: /** The single action row beneath a message's content: the per-message
279:  *  actions, then (assistant turns only) the context and usage affordances.
280:  *  Fork shows on BOTH roles, since the API forks from any message id, and is
281:  *  disabled rather than removed while a turn streams so the row keeps its
282:  *  shape. */
283: type ChatMessageActionProps = {
284:   message: UIMessage;
285:   availableModels: ReadonlyArray<AvailableModel>;
286:   chatId: string;
287:   status: ChatStatus;
288:   onForked: (forkedChatId: string) => void;
289:   onInspectContext: (runId: string) => void;
290:   /** The Chat's newest Run, which decides the latest turn's turn-level
291:    *  actions, and the follow-up sender those actions call. */
292:   latestRun: ChatLatestRunResponse | null;
293:   onFollowUp: (request: FollowUpRunRequest) => void;
294: };
295: 
296: /**
297:  * The row the actions sit in, owned here rather than by the vendored
298:  * `MessageActions`: transparent until its message is hovered or holds focus,
299:  * yet always in layout, so revealing it never shifts the transcript. It
300:  * stays revealed while one of its popups (the usage card) is open, since
301:  * that card is portaled outside the hovered message. Where the primary input
302:  * cannot hover (touch), `group-hover` never matches, so the row stays
303:  * visible. It sits under the user bubble's right edge, and on replies pulls
304:  * left so the first icon lines up with the text.
305:  */
306: function MessageActionRow({
307:   from,
308:   children,
309: }: {
310:   from: UIMessage["role"];
311:   children: ReactNode;
312: }) {
313:   return (
314:     <div
315:       className={cn(
316:         "flex flex-wrap items-center gap-1 text-muted-foreground opacity-0 transition-opacity group-hover/message:opacity-100 group-focus-within/message:opacity-100 group-has-[[data-popup-open]]/message:opacity-100 [@media(hover:none)]:opacity-100",
317:         from === "user" ? "justify-end" : "-ml-1.5",
318:       )}
319:     >
320:       {children}
321:     </div>
322:   );
323: }
324: 
325: type ChatMessageFooterProps = ChatMessageActionProps & { isLast: boolean };
326: 
327: /** Fork, disabled rather than removed while a turn streams. */
328: function MessageForkAction({
329:   message,
330:   chatId,
331:   status,
332:   onForked,
333: }: Pick<ChatMessageFooterProps, "message" | "chatId" | "status" | "onForked">) {
334:   return (
335:     <MessageForkButton
336:       chatId={chatId}
337:       fromMessageId={message.id}
338:       disabled={status !== "ready" && status !== "error"}
339:       onForked={onForked}
340:     />
341:   );
342: }
343: 
344: function UserMessageFooter(props: ChatMessageFooterProps) {
345:   return (
346:     <MessageActionRow from="user">
347:       <MessageCopyButton parts={props.message.parts} />
348:       <MessageActionButton
349:         label="Edit"
350:         icon={PencilIcon}
351:         tooltip="Edit — coming soon"
352:         disabled
353:       />
354:       <MessageForkAction {...props} />
355:     </MessageActionRow>
356:   );
357: }
358: 
359: /** The reply's action row: per-message actions, the turn-level actions the
360:  *  latest turn alone offers, fork, then the context receipt and usage. */
361: function AssistantMessageFooter({
362:   message,
363:   availableModels,
364:   chatId,
365:   status,
366:   onForked,
367:   onInspectContext,
368:   latestRun,
369:   onFollowUp,
370:   isLast,
371: }: ChatMessageFooterProps) {
372:   return (
373:     <MessageActionRow from="assistant">
374:       <MessageCopyButton parts={message.parts} />
375:       {isLast && (
376:         <TurnActions
377:           chatId={chatId}
378:           latestRun={latestRun}
379:           reply={message}
380:           status={status}
381:           onFollowUp={onFollowUp}
382:         />
383:       )}
384:       <MessageForkAction
385:         message={message}
386:         chatId={chatId}
387:         status={status}
